const resposta = $input.first().json.text || $input.first().json.content || '';

let dados;
try {
  const jsonMatch = resposta.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('JSON não encontrado');
  dados = JSON.parse(jsonMatch[0]);
} catch (e) {
  return [{ json: { erro: true, mensagem: 'Falha ao ler resposta do Claude: ' + e.message } }];
}

const mesesMap = {
  'janeiro':'Janeiro','fevereiro':'Fevereiro','março':'Março','marco':'Março',
  'abril':'Abril','maio':'Maio','junho':'Junho','julho':'Julho',
  'agosto':'Agosto','setembro':'Setembro','outubro':'Outubro',
  'novembro':'Novembro','dezembro':'Dezembro'
};

// Mês: usa o campo do formulário se preenchido, senão o detectado pela IA
const mesFormulario = $('Formulário – Upload de Fatura').first().json['Mês de referência (opcional – ex: Abril)'] || '';
const mesIA = (dados.mes || '').toLowerCase().trim();
const mes = mesFormulario || mesesMap[mesIA] || dados.mes || 'Indefinido';
const email = $('Formulário – Upload de Fatura').first().json['Seu e-mail (para receber os lançamentos)'] || '';

const lancamentos = (dados.lancamentos || []).map(l => ({
  mes,
  data:            l.data || '',
  descricao:       l.descricao || '',
  categoria:       l.categoria || 'Outros',
  tipo:            l.tipo || 'Despesa',
  valor:           parseFloat(l.valor) || 0,
  forma_pagamento: l.forma_pagamento || '',
  parcelas:        parseInt(l.parcelas) || 1,
  observacoes:     l.observacoes || ''
}));

const total_despesas = lancamentos.filter(l => l.tipo === 'Despesa').reduce((s,l) => s + l.valor, 0);
const total_receitas = lancamentos.filter(l => l.tipo === 'Receita').reduce((s,l) => s + l.valor, 0);

// Agrupar por categoria
const por_cat = {};
lancamentos.forEach(l => {
  if (l.tipo === 'Despesa') por_cat[l.categoria] = (por_cat[l.categoria]||0) + l.valor;
});
const top_cat = Object.entries(por_cat).sort((a,b)=>b[1]-a[1]).slice(0,5);

// Montar CSV
const csvHeader = 'Data,Descrição,Categoria,Tipo,Valor (R$),Forma Pagto,Parcelas,Observações';
const csvLinhas = lancamentos.map(l =>
  `"${l.data}","${l.descricao}","${l.categoria}","${l.tipo}","${l.valor.toFixed(2).replace('.',',')}","${l.forma_pagamento}","${l.parcelas}","${l.observacoes}"`
);
const csv = [csvHeader, ...csvLinhas].join('\n');

// Montar HTML do e-mail
const topCatHTML = top_cat.map(([c,v]) =>
  `<tr><td style="padding:6px 12px;border-bottom:1px solid #eee">${c}</td><td style="padding:6px 12px;border-bottom:1px solid #eee;text-align:right">R$ ${v.toFixed(2).replace('.',',')}</td></tr>`
).join('');

const linhasHTML = lancamentos.map(l =>
  `<tr>
    <td style="padding:5px 8px;border-bottom:1px solid #f0f0f0;white-space:nowrap">${l.data}</td>
    <td style="padding:5px 8px;border-bottom:1px solid #f0f0f0">${l.descricao}</td>
    <td style="padding:5px 8px;border-bottom:1px solid #f0f0f0">${l.categoria}</td>
    <td style="padding:5px 8px;border-bottom:1px solid #f0f0f0;color:${l.tipo==='Receita'?'#16a34a':'#dc2626'}">${l.tipo}</td>
    <td style="padding:5px 8px;border-bottom:1px solid #f0f0f0;text-align:right;font-weight:600">R$ ${l.valor.toFixed(2).replace('.',',')}</td>
    <td style="padding:5px 8px;border-bottom:1px solid #f0f0f0">${l.forma_pagamento}</td>
  </tr>`
).join('');

const html = `
<!DOCTYPE html>
<html>
<head><meta charset="UTF-8"></head>
<body style="font-family:Arial,sans-serif;max-width:800px;margin:0 auto;padding:20px;color:#1e1e2e">
  <div style="background:#1e1e2e;color:#fff;padding:24px;border-radius:12px;margin-bottom:24px">
    <h1 style="margin:0 0 4px">Controle Financeiro</h1>
    <p style="margin:0;color:#a0a0c0">Fatura processada – ${mes} · ${dados.banco || ''}</p>
  </div>

  <div style="display:flex;gap:16px;margin-bottom:24px;flex-wrap:wrap">
    <div style="flex:1;min-width:160px;background:#dcfce7;border-radius:8px;padding:16px">
      <div style="font-size:12px;color:#166534;font-weight:600">RECEITAS</div>
      <div style="font-size:22px;font-weight:700;color:#16a34a">R$ ${total_receitas.toFixed(2).replace('.',',')}</div>
    </div>
    <div style="flex:1;min-width:160px;background:#fee2e2;border-radius:8px;padding:16px">
      <div style="font-size:12px;color:#991b1b;font-weight:600">DESPESAS</div>
      <div style="font-size:22px;font-weight:700;color:#dc2626">R$ ${total_despesas.toFixed(2).replace('.',',')}</div>
    </div>
    <div style="flex:1;min-width:160px;background:#ede9fe;border-radius:8px;padding:16px">
      <div style="font-size:12px;color:#5b21b6;font-weight:600">SALDO</div>
      <div style="font-size:22px;font-weight:700;color:#7c3aed">R$ ${(total_receitas-total_despesas).toFixed(2).replace('.',',')}</div>
    </div>
    <div style="flex:1;min-width:160px;background:#fef9c3;border-radius:8px;padding:16px">
      <div style="font-size:12px;color:#854d0e;font-weight:600">LANÇAMENTOS</div>
      <div style="font-size:22px;font-weight:700;color:#ca8a04">${lancamentos.length}</div>
    </div>
  </div>

  <h2 style="font-size:16px;margin-bottom:8px">Top Categorias</h2>
  <table style="width:100%;border-collapse:collapse;margin-bottom:24px;background:#f9f9f9;border-radius:8px;overflow:hidden">
    ${topCatHTML}
  </table>

  <h2 style="font-size:16px;margin-bottom:8px">Todos os Lançamentos</h2>
  <p style="font-size:13px;color:#666;margin-bottom:8px">Cole no Excel: selecione a tabela abaixo → Ctrl+C → abra o Excel na aba do mês → Ctrl+V</p>
  <table style="width:100%;border-collapse:collapse;font-size:13px">
    <thead>
      <tr style="background:#1e1e2e;color:#fff">
        <th style="padding:8px;text-align:left">Data</th>
        <th style="padding:8px;text-align:left">Descrição</th>
        <th style="padding:8px;text-align:left">Categoria</th>
        <th style="padding:8px;text-align:left">Tipo</th>
        <th style="padding:8px;text-align:right">Valor</th>
        <th style="padding:8px;text-align:left">Forma</th>
      </tr>
    </thead>
    <tbody>${linhasHTML}</tbody>
  </table>

  <p style="margin-top:24px;font-size:12px;color:#999">Gerado automaticamente · Revise os lançamentos antes de usar.</p>
</body>
</html>`;

return [{ json: { mes, email, banco: dados.banco||'', lancamentos, total_despesas, total_receitas, csv, html, quantidade: lancamentos.length } }];

// Converte CSV em arquivo binário para anexo do e-mail
const csv = $input.first().json.csv;
const mes = $input.first().json.mes;
const nomeArquivo = `lancamentos_${mes.toLowerCase()}.csv`;

// Passa todos os campos adiante + arquivo binário
const item = $input.first();
item.binary = item.binary || {};
item.binary.csvFile = await this.helpers.prepareBinaryData(
  Buffer.from('\uFEFF' + csv, 'utf-8'),  // BOM para Excel reconhecer UTF-8
  nomeArquivo,
  'text/csv'
);

return [item];
